        major_themes:
          report.major_themes || [],

        positive_feedback:
          report.positive_feedback || [],

        negative_feedback:
          report.negative_feedback || [],

        pain_points:
          report.pain_points || [],

        product_strengths:
          report.product_strengths || [],

        product_weaknesses:
          report.product_weaknesses || [],

        feature_requests:
          report.feature_requests || [],

        improvement_opportunities:
          report.improvement_opportunities || [],

        retention_risks:
          report.retention_risks || [],

        priority_issues:
          report.priority_issues || [],

        recommended_actions:
          report.recommended_actions || [],

        business_impact:
          report.business_impact || "Unknown",

        overall_feedback_status:
          report.overall_feedback_status || "Unknown",

        final_assessment:
          report.final_assessment || "Unknown",

        parse_status: "success"
